INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0201-0001-0001-000000000001', '22222222-0002-0001-0001-000000000001', 'What is a Variable?', 'Meet al-Khwarizmi and discover how letters replaced words in mathematics', 1, 'tutorial', 15, 5, 820, 'Muhammad ibn Musa al-Khwarizmi',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0201-0001-0001-000000000001', '33333333-0201-0001-0001-000000000001', 'multiple_choice', 'easy', 'What does a variable represent in mathematics?', NULL, '[{"id":"a","text":"A fixed number that never changes"},{"id":"b","text":"An unknown value or a value that can change"},{"id":"c","text":"The answer to every equation"},{"id":"d","text":"A type of fraction"}]'::jsonb, '"b"'::jsonb, 'A variable represents an unknown or changeable value. That is why we use letters like x — they stand in for numbers we need to find.', 'Think about what the letter x stands for in x + 3 = 7', 5, 1),
('44444444-0201-0001-0001-000000000002', '33333333-0201-0001-0001-000000000001', 'fill_in_blank', 'easy', 'The word "algebra" comes from the Arabic word al-jabr. What does al-jabr mean?', NULL, NULL, '"completion"'::jsonb, 'Al-jabr means completion or restoration. It comes from the title of al-Khwarizmi''s famous book on solving equations.', 'It is one of two Arabic words in the book title', 5, 2),
('44444444-0201-0001-0001-000000000003', '33333333-0201-0001-0001-000000000001', 'multiple_choice', 'easy', 'If x = 4, what is x + 7?', 'x + 7 = ?', '[{"id":"a","text":"10"},{"id":"b","text":"11"},{"id":"c","text":"12"},{"id":"d","text":"7"}]'::jsonb, '"b"'::jsonb, 'Replace x with 4: 4 + 7 = 11. That is how variables work — you substitute the value and calculate.', 'Replace the letter with the number', 5, 3),
('44444444-0201-0001-0001-000000000004', '33333333-0201-0001-0001-000000000001', 'true_false', 'easy', 'True or False: Al-Khwarizmi worked at the House of Wisdom in Baghdad.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! The House of Wisdom was a major intellectual center in 9th-century Baghdad where al-Khwarizmi did his groundbreaking work.', 'Think about where the story said he worked', 5, 4),
('44444444-0201-0001-0001-000000000005', '33333333-0201-0001-0001-000000000001', 'fill_in_blank', 'easy', 'If y = 3, what is 2y? (Type just the number)', '2y = ?', NULL, '"6"'::jsonb, '2y means 2 times y. If y = 3, then 2 × 3 = 6. In algebra, writing a number next to a variable means multiplication.', 'The number next to the letter means multiply', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0201-0001-0001-000000000002', '22222222-0002-0001-0001-000000000001', 'Writing Expressions', 'Turn everyday language into algebraic expressions', 2, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0201-0002-0001-000000000001', '33333333-0201-0001-0001-000000000002', 'multiple_choice', 'easy', 'How would you write "5 more than a number n" as an expression?', NULL, '[{"id":"a","text":"5n"},{"id":"b","text":"n + 5"},{"id":"c","text":"n - 5"},{"id":"d","text":"5 - n"}]'::jsonb, '"b"'::jsonb, '"More than" means addition. So 5 more than n is n + 5.', '"More than" tells you which operation to use', 5, 1),
('44444444-0201-0002-0001-000000000002', '33333333-0201-0001-0001-000000000002', 'multiple_choice', 'easy', 'How would you write "twice a number x" as an expression?', NULL, '[{"id":"a","text":"x + 2"},{"id":"b","text":"x / 2"},{"id":"c","text":"2x"},{"id":"d","text":"x²"}]'::jsonb, '"c"'::jsonb, '"Twice" means two times. In algebra, 2 times x is written as 2x (the number goes in front of the variable).', '"Twice" means multiplied by 2', 5, 2),
('44444444-0201-0002-0001-000000000003', '33333333-0201-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Write "a number decreased by 4" using the variable n. (Type the expression)', NULL, NULL, '"n - 4"'::jsonb, '"Decreased by" means subtraction. A number n decreased by 4 is n - 4.', '"Decreased" means you are taking away', 5, 3),
('44444444-0201-0002-0001-000000000004', '33333333-0201-0001-0001-000000000002', 'multiple_choice', 'easy', 'What does the expression 3x + 1 mean in words?', NULL, '[{"id":"a","text":"Three plus x plus one"},{"id":"b","text":"Three times a number, then add one"},{"id":"c","text":"One more than three"},{"id":"d","text":"x divided by 3 plus 1"}]'::jsonb, '"b"'::jsonb, '3x means 3 times x. Then + 1 means add one. So it is "three times a number, then add one."', 'Remember that a number next to a letter means multiplication', 5, 4),
('44444444-0201-0002-0001-000000000005', '33333333-0201-0001-0001-000000000002', 'true_false', 'easy', 'True or False: The expression x/3 means "a number divided by 3."', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! x/3 is the algebraic way to write "x divided by 3." The slash means division.', 'What does the / symbol mean?', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0201-0001-0001-000000000003', '22222222-0002-0001-0001-000000000001', 'Evaluating Expressions', 'Plug in values and calculate the result', 3, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0201-0003-0001-000000000001', '33333333-0201-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Evaluate 3x + 2 when x = 5. (Type just the number)', '3(5) + 2 = ?', NULL, '"17"'::jsonb, '3 × 5 = 15, then 15 + 2 = 17. Always do multiplication before addition.', 'Replace x with 5, multiply first, then add', 5, 1),
('44444444-0201-0003-0001-000000000002', '33333333-0201-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Evaluate 10 - 2n when n = 3. (Type just the number)', '10 - 2(3) = ?', NULL, '"4"'::jsonb, '2 × 3 = 6, then 10 - 6 = 4. Multiply first, then subtract.', 'First calculate 2 times 3, then subtract from 10', 5, 2),
('44444444-0201-0003-0001-000000000003', '33333333-0201-0001-0001-000000000003', 'multiple_choice', 'easy', 'What is the value of a² + 1 when a = 4?', 'a^2 + 1 = ?', '[{"id":"a","text":"9"},{"id":"b","text":"17"},{"id":"c","text":"5"},{"id":"d","text":"16"}]'::jsonb, '"b"'::jsonb, 'a² means a × a. So 4² = 4 × 4 = 16. Then 16 + 1 = 17.', 'Squaring means multiplying a number by itself', 5, 3),
('44444444-0201-0003-0001-000000000004', '33333333-0201-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Evaluate (x + y) / 2 when x = 8 and y = 6. (Type just the number)', NULL, NULL, '"7"'::jsonb, '(8 + 6) / 2 = 14 / 2 = 7. This formula actually calculates the average of two numbers!', 'Add first (parentheses), then divide', 5, 4),
('44444444-0201-0003-0001-000000000005', '33333333-0201-0001-0001-000000000003', 'multiple_choice', 'easy', 'If p = 2 and q = 5, what is 4p - q?', '4p - q = ?', '[{"id":"a","text":"1"},{"id":"b","text":"3"},{"id":"c","text":"7"},{"id":"d","text":"13"}]'::jsonb, '"b"'::jsonb, '4p = 4 × 2 = 8. Then 8 - q = 8 - 5 = 3.', 'Calculate 4 times p first, then subtract q', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0201-0001-0001-000000000004', '22222222-0002-0001-0001-000000000001', 'Simplifying Expressions', 'Combine like terms to make expressions shorter', 4, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0201-0004-0001-000000000001', '33333333-0201-0001-0001-000000000004', 'multiple_choice', 'easy', 'Simplify: 3x + 5x', '3x + 5x = ?', '[{"id":"a","text":"8x"},{"id":"b","text":"15x"},{"id":"c","text":"8x²"},{"id":"d","text":"35x"}]'::jsonb, '"a"'::jsonb, '3x and 5x are "like terms" because they both have x. 3 + 5 = 8, so 3x + 5x = 8x.', 'Like terms have the same variable — just add the numbers in front', 5, 1),
('44444444-0201-0004-0001-000000000002', '33333333-0201-0001-0001-000000000004', 'fill_in_blank', 'easy', 'Simplify: 7a - 2a (Type the simplified expression)', '7a - 2a = ?', NULL, '"5a"'::jsonb, '7a - 2a = 5a. Both terms have the variable a, so subtract the coefficients: 7 - 2 = 5.', 'Subtract the numbers in front of the a', 5, 2),
('44444444-0201-0004-0001-000000000003', '33333333-0201-0001-0001-000000000004', 'multiple_choice', 'easy', 'Simplify: 2x + 3 + 4x + 1', NULL, '[{"id":"a","text":"6x + 4"},{"id":"b","text":"10x"},{"id":"c","text":"6x + 31"},{"id":"d","text":"9x + 1"}]'::jsonb, '"a"'::jsonb, 'Combine like terms: 2x + 4x = 6x (variable terms) and 3 + 1 = 4 (constant terms). Answer: 6x + 4.', 'Group the x terms together and the number terms together', 5, 3),
('44444444-0201-0004-0001-000000000004', '33333333-0201-0001-0001-000000000004', 'true_false', 'easy', 'True or False: 3x and 3y are like terms that can be combined.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'False! Like terms must have the same variable. 3x has x and 3y has y — different variables, so they cannot be combined.', 'Look at the letters, not just the numbers', 5, 4),
('44444444-0201-0004-0001-000000000005', '33333333-0201-0001-0001-000000000004', 'fill_in_blank', 'easy', 'Simplify: 5m + 2n + 3m (Type the simplified expression)', NULL, NULL, '"8m + 2n"'::jsonb, '5m + 3m = 8m (like terms). 2n stays as is (no other n terms). Answer: 8m + 2n.', 'Only combine terms with the same variable letter', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0201-0001-0001-000000000005', '22222222-0002-0001-0001-000000000001', 'Variables Boss Round', 'Show what you know about variables and expressions!', 5, 'boss_round', 25, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0201-0005-0001-000000000001', '33333333-0201-0001-0001-000000000005', 'fill_in_blank', 'medium', 'Evaluate 2x² - 3x + 1 when x = 3. (Type just the number)', '2(3)^2 - 3(3) + 1 = ?', NULL, '"10"'::jsonb, '2(9) - 9 + 1 = 18 - 9 + 1 = 10. Remember: exponents first, then multiplication, then add/subtract.', 'First square 3, then multiply, then combine', 10, 1),
('44444444-0201-0005-0001-000000000002', '33333333-0201-0001-0001-000000000005', 'multiple_choice', 'medium', 'Which expression means "the sum of a number and 7, divided by 2"?', NULL, '[{"id":"a","text":"n + 7 / 2"},{"id":"b","text":"(n + 7) / 2"},{"id":"c","text":"n / 2 + 7"},{"id":"d","text":"2(n + 7)"}]'::jsonb, '"b"'::jsonb, 'You need parentheses to show that the ENTIRE sum (n + 7) gets divided by 2. Without them, only 7 gets divided.', 'The word "sum" needs to happen before the division', 10, 2),
('44444444-0201-0005-0001-000000000003', '33333333-0201-0001-0001-000000000005', 'fill_in_blank', 'medium', 'Simplify: 4a + 3b - 2a + b (Type the simplified expression)', NULL, NULL, '"2a + 4b"'::jsonb, '4a - 2a = 2a and 3b + b = 4b. Answer: 2a + 4b.', 'Group the a terms and the b terms separately', 10, 3),
('44444444-0201-0005-0001-000000000004', '33333333-0201-0001-0001-000000000005', 'multiple_choice', 'medium', 'Al-Khwarizmi is also the origin of which other important mathematical word?', NULL, '[{"id":"a","text":"Geometry"},{"id":"b","text":"Algorithm"},{"id":"c","text":"Calculus"},{"id":"d","text":"Arithmetic"}]'::jsonb, '"b"'::jsonb, 'The word algorithm comes from the Latin version of al-Khwarizmi''s name (Algoritmi). Both algebra AND algorithm trace back to this one mathematician.', 'His name was Latinized in medieval Europe', 10, 4),
('44444444-0201-0005-0001-000000000005', '33333333-0201-0001-0001-000000000005', 'fill_in_blank', 'medium', 'If the perimeter of a square is 4s, and s = 6.5 cm, what is the perimeter? (Type number only)', '4(6.5) = ?', NULL, '"26"'::jsonb, '4 × 6.5 = 26 cm. This is algebra in action — the formula 4s works for ANY square, no matter the side length.', 'Multiply 4 by 6.5', 10, 5)
